#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;cin>>s;
vector<int>g;int i=0,n=s.size();
while(i<n){int j=i;while(j<n&&s[j]==s[i])++j;g.push_back(j-i);i=j;}
long long r=0;
for(size_t k=0;k+1<g.size();++k)r+=min(g[k],g[k+1]);
printf("%lld\n",r);return 0;}

